<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/ai.php';$admin=require_admin($pdo);$success='';$error='';$test='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$op=(string)($_POST['op']??'');try{
 if($op==='provider'){$id=(int)($_POST['provider_id']??0);$label=trim((string)($_POST['label']??''));$type=(string)($_POST['provider_type']??'openai');$base=trim((string)($_POST['api_base_url']??''));$key=trim((string)($_POST['api_key']??''));$enabled=isset($_POST['enabled'])?1:0;if(!in_array($type,['openai','anthropic','gemini','openai_compatible'],true)||$label==='')throw new RuntimeException('Provider label/type is invalid.');if($id){$params=[$label,$type,$base?:null,$enabled];$sql='UPDATE ai_providers SET label=?,provider_type=?,api_base_url=?,enabled=?';if($key!==''){$sql.=',api_key_ciphertext=?';$params[]=ai_encrypt_secret($config,$key);}$sql.=' WHERE id=?';$params[]=$id;$pdo->prepare($sql)->execute($params);}else{$pdo->prepare('INSERT INTO ai_providers(public_id,label,provider_type,api_base_url,api_key_ciphertext,enabled) VALUES(?,?,?,?,?,?)')->execute([ulid_like(),$label,$type,$base?:null,$key!==''?ai_encrypt_secret($config,$key):null,$enabled]);}$success='Provider saved.';}
 if($op==='model'){$provider=(int)($_POST['provider_id']??0);$name=trim((string)($_POST['model_name']??''));$display=trim((string)($_POST['display_name']??''));if(!$provider||$name===''||$display==='')throw new RuntimeException('Model fields are required.');$pdo->prepare('INSERT INTO ai_models(public_id,provider_id,model_name,display_name,enabled,admin_enabled,pro_enabled,max_output_tokens) VALUES(?,?,?,?,?,?,?,?)')->execute([ulid_like(),$provider,$name,$display,isset($_POST['enabled'])?1:0,isset($_POST['admin_enabled'])?1:0,isset($_POST['pro_enabled'])?1:0,max(256,(int)($_POST['max_output_tokens']??2048))]);$success='Model added.';}
 if($op==='model_flags'){$id=(int)($_POST['model_id']??0);$pdo->prepare('UPDATE ai_models SET enabled=?,admin_enabled=?,pro_enabled=?,max_output_tokens=? WHERE id=?')->execute([isset($_POST['enabled'])?1:0,isset($_POST['admin_enabled'])?1:0,isset($_POST['pro_enabled'])?1:0,max(256,(int)($_POST['max_output_tokens']??2048)),$id]);$success='Model access updated.';}
 if($op==='settings'){$vals=[];foreach(['admin_default_model_id','pro_default_model_id','source_monitor_model_id','moderation_model_id','research_model_id','transcript_cleanup_model_id','annotation_intelligence_model_id'] as $f)$vals[]=($_POST[$f]??'')!==''?(int)$_POST[$f]:null;$vals[]=$admin['id'];$pdo->prepare('UPDATE ai_settings SET admin_default_model_id=?,pro_default_model_id=?,source_monitor_model_id=?,moderation_model_id=?,research_model_id=?,transcript_cleanup_model_id=?,annotation_intelligence_model_id=?,updated_by_user_id=? WHERE id=1')->execute($vals);$success='AI routing updated.';}
 if($op==='test'){$id=(int)($_POST['model_id']??0);$r=ai_run($pdo,$config,$admin,'admin','admin_model_test',$id,'You are the Annotated backend model health check. Answer concisely.','Reply exactly with: Annotated AI connection is working.',['test'=>true],'admin','ai');$test=$r['text'];$success='Model test completed.';}
}catch(Throwable $e){$error=$e->getMessage();}}
$providers=$pdo->query('SELECT * FROM ai_providers ORDER BY label')->fetchAll();$models=$pdo->query('SELECT m.*,p.label provider_label,p.provider_type FROM ai_models m JOIN ai_providers p ON p.id=m.provider_id ORDER BY p.label,m.display_name')->fetchAll();$settings=$pdo->query('SELECT * FROM ai_settings WHERE id=1')->fetch()?:[];$runs=$pdo->query('SELECT r.*,m.display_name model_name FROM ai_runs r LEFT JOIN ai_models m ON m.id=r.model_id ORDER BY r.created_at DESC LIMIT 20')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI · Annotated Admin</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/admin/">Annotated Admin</a><nav><a href="/admin/source-monitor.php">Sources</a><a href="/admin/moderation.php">Moderation</a><a href="/admin/users.php">Users</a></nav></header><main class="layout"><section><div class="pageTitle"><span class="eyebrow">AI BACKEND</span><h1>LLM providers & task routing</h1><p>API keys are encrypted at rest with <code>app.encryption_key</code>. Pro users can only use models explicitly marked Pro.</p></div><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><?php if($test):?><div class="card"><strong>Test result</strong><p><?=nl2br(h($test))?></p></div><?php endif?><div class="card"><h2>Models</h2><?php foreach($models as $m):?><form method="post" class="modelRow"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="model_flags"><input type="hidden" name="model_id" value="<?=h((string)$m['id'])?>"><div><strong><?=h($m['display_name'])?></strong><div class="meta"><?=h($m['provider_label'])?> · <?=h($m['model_name'])?></div></div><label><input type="checkbox" name="enabled" <?=$m['enabled']?'checked':''?>> Enabled</label><label><input type="checkbox" name="admin_enabled" <?=$m['admin_enabled']?'checked':''?>> Admin</label><label><input type="checkbox" name="pro_enabled" <?=$m['pro_enabled']?'checked':''?>> Pro</label><input type="number" name="max_output_tokens" value="<?=h((string)$m['max_output_tokens'])?>" min="256"><button>Save</button></form><?php endforeach?></div><div class="card"><h2>Task routing</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="settings"><?php foreach(['admin_default_model_id'=>'Admin default','pro_default_model_id'=>'Pro default','source_monitor_model_id'=>'Source monitoring','moderation_model_id'=>'Moderation triage','research_model_id'=>'Research synthesis','transcript_cleanup_model_id'=>'Transcript cleanup','annotation_intelligence_model_id'=>'Annotation intelligence'] as $f=>$label):?><label><?=h($label)?><select name="<?=$f?>"><option value="">None</option><?php foreach($models as $m):?><option value="<?=h((string)$m['id'])?>" <?=((string)($settings[$f]??'')===(string)$m['id'])?'selected':''?>><?=h($m['display_name'])?> · <?=h($m['provider_label'])?></option><?php endforeach?></select></label><?php endforeach?><button>Save routing</button></form></div><div class="card"><h2>Recent AI runs</h2><?php foreach($runs as $r):?><div class="historyItem"><strong><?=h($r['task_type'])?></strong> · <?=h($r['status'])?> · <?=h($r['model_name'])?><div class="meta"><?=h($r['created_at'])?> · <?=h($r['initiated_by'])?></div><?php if($r['output_text']):?><details><summary>Output</summary><p><?=nl2br(h(mb_substr($r['output_text'],0,3000)))?></p></details><?php endif?></div><?php endforeach?></div></section><aside><div class="card"><h3>Add provider</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="provider"><label>Label<input name="label" required placeholder="OpenAI production"></label><label>Type<select name="provider_type"><option value="openai">OpenAI</option><option value="anthropic">Anthropic</option><option value="gemini">Google Gemini</option><option value="openai_compatible">OpenAI-compatible</option></select></label><label>API base URL<input name="api_base_url" placeholder="optional"></label><label>API key<input type="password" name="api_key" required></label><label><input type="checkbox" name="enabled" checked> Enabled</label><button>Add provider</button></form></div><?php foreach($providers as $p):?><div class="card"><h3><?=h($p['label'])?></h3><div class="meta"><?=h($p['provider_type'])?> · key <?=empty($p['api_key_ciphertext'])?'missing':'stored'?></div></div><?php endforeach?><div class="card"><h3>Add model</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="model"><label>Provider<select name="provider_id" required><?php foreach($providers as $p):?><option value="<?=h((string)$p['id'])?>"><?=h($p['label'])?></option><?php endforeach?></select></label><label>Model ID<input name="model_name" required placeholder="provider model id"></label><label>Display name<input name="display_name" required></label><label>Max output tokens<input type="number" name="max_output_tokens" value="2048" min="256"></label><label><input type="checkbox" name="enabled" checked> Enabled</label><label><input type="checkbox" name="admin_enabled" checked> Admin</label><label><input type="checkbox" name="pro_enabled"> Pro</label><button>Add model</button></form></div><div class="card"><h3>Test a model</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="test"><select name="model_id" required><?php foreach($models as $m):?><option value="<?=h((string)$m['id'])?>"><?=h($m['display_name'])?></option><?php endforeach?></select><button>Run test</button></form></div></aside></main></body></html>
